-- Bloco 4/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'No Segundo Diálogo, que resposta o espírita dá à objeção de que o estudo do Espiritismo produziria a loucura?', 'O Espiritismo verdadeiro, longe de produzir a loucura, previne-a e consola as aflições pela fé raciocinada na vida futura e na justiça divina.', 'Admite que metade dos médiuns acaba perdendo a razão após alguns anos.', 'Recomenda que apenas médicos psiquiatras estudem as obras da Codificação.', 'Afirma que a loucura é sempre um castigo físico incurável sem relação com o cérebro.', 'Reconhece que qualquer estudo filosófico ou religioso destrói o sistema nervoso.', 'A', 'Qualquer ideia exagerada em um cérebro já predisposto e enfraquecido pode desencadear delírios (como na política, nas paixões ou no fanatismo religioso), mas o estudo calmo e racional do Espiritismo fortalece a alma contra o desespero.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
  ('o_que_e_espiritismo', 'No diálogo com o Cético, por que os fenômenos espíritas não podem ser repetidos à vontade, como uma experiência física ou química de laboratório?', 'Porque os fluidos espirituais evaporam na presença de luz solar.', 'Porque os Espíritos são seres livres e inteligentes, e não máquinas nem reagentes químicos submetidos ao capricho dos observadores.', 'Porque os médiuns perdem suas faculdades diante de mais de três pessoas.', 'Porque a gravidade terrestre anula o perispírito durante o dia.', 'Porque as leis civis proíbem experiências científicas com médiuns.', 'B', 'As ciências físicas operam sobre a matéria inerte que se manipula à vontade; o Espiritismo lida com inteligências livres que têm vontade própria e não se prestam a exigências frívolas de curiosos.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'expert', true),
  ('o_que_e_espiritismo', 'Segundo explica Kardec ao Cético, qual foi a utilidade providencial dos fenômenos materiais (mesas girantes e pancadas) no início do Espiritismo?', 'Demonstrar que os Espíritos preferem comunicar-se por objetos de madeira.', 'Substituir definitivamente a imprensa escrita na transmissão dos ensinos morais.', 'Chamar a atenção dos homens pelos sentidos físicos e vencer a incredulidade materialista, servindo de prelúdio ao ensino filosófico.', 'Provar que apenas os Espíritos inferiores podem agir sobre a matéria.', 'Criar uma nova fonte de energia mecânica para a indústria europeia.', 'C', 'Os fenômenos físicos foram o vestíbulo da Ciência: falavam aos olhos para despertar a atenção de uma geração incrédula, abrindo caminho para as comunicações inteligentes e morais.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
  ('o_que_e_espiritismo', 'No Segundo Diálogo, como o espírita explica ao Cético a justiça das desigualdades de aptidões intelectuais e morais que as crianças trazem desde o berço?', 'Pelo acaso genético resultante apenas da alimentação materna.', 'Pelo privilégio arbitrário concedido por Deus a certas almas recém-criadas.', 'Pela influência astrológica da posição dos planetas no instante do parto.', 'Pela preexistência da alma e pela pluralidade das existências (reencarnação), em que cada Espírito traz o patrimônio adquirido em vidas anteriores.', 'Pela transmissão hereditária da própria alma dos pais para os filhos.', 'D', 'Se Deus criasse almas novas a cada nascimento com aptidões tão desiguais, seria parcial; a reencarnação explica que uns já viveram e progrediram mais do que outros em existências precedentes.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'dificil', true),
  ('o_que_e_espiritismo', 'Quando o Cético pergunta se o Espírito pode retrogradar e reencarnar no corpo de um animal, o que responde a Doutrina Espírita?', 'Sim, como punição temporária para os grandes criminosos da humanidade.', 'Sim, sempre que o homem se entrega aos instintos puramente sensuais.', 'Depende da decisão dos Espíritos Superiores em cada julgamento.', 'Apenas nas espécies domésticas mais próximas do convívio humano.', 'Não; o progresso do Espírito é contínuo: ele pode estacionar, mas jamais retrograda, sendo a metempsicose nos animais contrária à lei divina.', 'E', 'Kardec distingue claramente a reencarnação espírita da antiga metempsicose: o Espírito humano nunca volta a ser animal; se estaciona, reencarna em condições humanas de expiação para avançar.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'expert', true),
  ('o_que_e_espiritismo', 'No Segundo Diálogo, todas as reencarnações do Espírito ocorrem exclusivamente no planeta Terra?', 'Não; a Terra é apenas um dos numerosos mundos habitados, e as reencarnações ocorrem em diferentes globos conforme o adiantamento do Espírito.', 'Sim, pois a Terra é o único planeta habitado do universo.', 'Sim, porque o perispírito humano não suporta a atmosfera de outros orbes.', 'Não, pois cada Espírito só encarna uma única vez na Terra e nunca mais retorna.', 'Apenas os Espíritos perfeitos reencarnam na Lua e no Sol.', 'A', 'As diversas existências corporais podem realizar-se na Terra ou em outros mundos materiais mais ou menos adiantados, segundo a máxima evangélica de que ''há muitas moradas na casa de meu Pai''.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'facil', true),
  ('o_que_e_espiritismo', 'Ao final do Segundo Diálogo, que tríplice efeito moral produz no homem a convicção profunda das verdades ensinadas pelo Espiritismo?', 'Isolamento monástico, desprezo pela ciência e temor constante da morte.', 'Paciência e resignação nas provas da vida, afastamento do suicídio e prática sincera da caridade e fraternidade.', 'Ambição política, orgulho intelectual e busca de privilégios sociais.', 'Indiferença diante do sofrimento alheio, fatalismo passivo e ociosidade.', 'Crença na salvação exclusiva por fórmulas exteriores e rituais.', 'B', 'Compreendendo que a vida terrestre é breve estação de aprendizado, o homem encara a morte sem pavor, suporta as vicissitudes com coragem, repele o suicídio e esforça-se no bem.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true),
  ('o_que_e_espiritismo', 'No Terceiro Diálogo (''O Padre''), como o espírita responde à afirmação eclesiástica de que apenas o demônio e seus anjos decaídos podem comunicar-se com os homens?', 'Concordando que as almas humanas permanecem adormecidas até o juízo final.', 'Afirmando que os maus Espíritos não existem no plano espiritual.', 'Mostrando que seria absurdo e contrário à bondade de Deus conceder liberdade de ação apenas ao espírito do mal e proibir as boas almas de consolar e instruir os vivos.', 'Dizendo que os Espíritos só se comunicam dentro dos templos consagrados.', 'Alegando que o Antigo e o Novo Testamento jamais mencionam manifestações espirituais.', 'C', 'Kardec argumenta com lógica irrefutável: se Deus permite que os maus Espíritos tentem os homens, com muito mais razão permite que os bons Espíritos venham ampará-los e encaminhá-los ao bem.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'medio', true),
  ('o_que_e_espiritismo', 'No Terceiro Diálogo com o Padre, qual é o critério seguro apontado pelo Espiritismo para distinguir se um Espírito comunicante é bom ou mau?', 'O nome famoso ou sagrado com que ele assina a mensagem.', 'A beleza caligráfica da escrita psicografada pelo médium.', 'A intensidade das pancadas ou o peso da mesa que se levanta.', 'A qualidade moral de sua linguagem e de seus conselhos, pois ''reconhece-se a árvore pelo fruto'': um Espírito que só ensina a caridade e o bem não pode ser mau.', 'O horário noturno ou diurno em que ocorre a reunião mediúnica.', 'D', 'Aplicando a máxima de Jesus (''Pelos seus frutos os conhecereis''), Kardec lembra que o demônio não poderia pregar o amor a Deus, o perdão das ofensas, a humildade e a caridade sem destruir seu próprio reino.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'facil', true),
  ('o_que_e_espiritismo', 'Quando o Padre cita a proibição mosaica de interrogar os mortos (Deuteronômio), que explicação histórica e doutrinária o espírita apresenta?', 'Que Moisés desconhecia totalmente a existência da alma imortal.', 'Que o texto bíblico foi inventado apenas no século XVIII.', 'Que Moisés proibiu apenas a escrita manual, mas permitiu as mesas girantes.', 'Que a lei mosaica só se aplicava aos sacerdotes egípcios e babilônios.', 'Que Moisés reprimiu o abuso supersticioso da adivinhação mercenária e idólatra entre os hebreus, e que essa própria proibição prova que a comunicação com os mortos era real.', 'E', 'Não se proíbe aquilo que não existe: Moisés vetou a evocação transformada em ofício de adivinhação e comércio supersticioso, ao passo que o Espiritismo condena esses mesmos abusos e busca a edificação moral.', 'O Que é o Espiritismo - Cap. I, Terceiro Diálogo: O Padre', 'expert', true);

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';